import{_ as p,a0 as r,w as h,s as o,ao as l,I as n,x as a,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const B=JSON.parse('{"title":"Bash 基础知识系列 #5：在 Bash 中使用数组 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 基础知识系列 #5：在 Bash 中使用数组 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 基础知识系列 #5：在 Bash 中使用数组 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 基础知识系列 #5：在 Bash 中使用数组 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230710.1 ⭐️ Bash Basics Series 5 Using Arrays in Bash","title":"Bash 基础知识系列 #5：在 Bash 中使用数组","tag":"202307","desc":""},"relativePath":"202307/20230710.1 ⭐️ Bash Basics Series 5 Using Arrays in Bash.md","filePath":"[post].md"}'),d={name:"202307/20230710.1 ⭐️ Bash Basics Series 5 Using Arrays in Bash.md"};function g(b,s,k,u,c,m){const e=r("Link");return h(),o("div",null,[s[23]||(s[23]=l('<h1 id="bash-基础知识系列-5-在-bash-中使用数组" tabindex="-1">Bash 基础知识系列 #5：在 Bash 中使用数组 <a class="header-anchor" href="#bash-基础知识系列-5-在-bash-中使用数组" aria-label="Permalink to “Bash 基础知识系列 #5：在 Bash 中使用数组”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/20/150302ttfmzchutthfcncm.jpg" alt=""></p><blockquote><p>本章将介绍如何在 Bash Shell 脚本中使用数组。学习添加元素、删除元素和获取数组长度。</p></blockquote><p>在本系列的前面部分中，你了解了变量。变量中可以有单个值。</p><p>数组内部可以有多个值。当你必须一次处理多个变量时，这会使事情变得更容易。你不必将各个值存储在新变量中。</p><p>因此，不要像这样声明五个变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>distro1=Ubuntu</span></span>\n<span class="line"><span>distro2=Fedora</span></span>\n<span class="line"><span>distro3=SUSE</span></span>\n<span class="line"><span>distro4=Arch Linux</span></span>\n<span class="line"><span>distro5=Nix</span></span></code></pre></div><p>你可以在单个数组中初始化它们所有：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>distros=(Ubuntu Fedora SUSE &quot;Arch Linux&quot; Nix)</span></span></code></pre></div><p>与其他一些编程语言不同，你不使用逗号作为数组元素分隔符。</p><p>那挺好的。让我们看看如何访问数组元素。</p><h3 id="在-bash-中访问数组元素" tabindex="-1">在 Bash 中访问数组元素 <a class="header-anchor" href="#在-bash-中访问数组元素" aria-label="Permalink to “在 Bash 中访问数组元素”">​</a></h3><p>使用索引（数组中的位置）访问数组元素。要访问索引 N 处的数组元素，请使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>${array_name[N]}</span></span></code></pre></div><blockquote><p>💡 与大多数其他编程语言一样，Bash Shell 中的数组从索引 0 开始。这意味着第一个元素的索引为 0，第二个元素的索引为 1，第 n 个元素的索引为 <code>n-1</code>。</p></blockquote><p>因此，如果你想打印 SUSE，你将使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo ${distros[2]}</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/07/accessing-array-elements-bash.png" alt="Example of accessing array elements in bash shell"></p><blockquote><p>🚧 <code>${</code> 之后或 <code>}</code> 之前不能有任何空格。你不能像 <code>${ array[n] }</code> 那样使用它。</p></blockquote><h3 id="一次访问所有数组元素" tabindex="-1">一次访问所有数组元素 <a class="header-anchor" href="#一次访问所有数组元素" aria-label="Permalink to “一次访问所有数组元素”">​</a></h3><p>假设你要打印数组的所有元素。</p><p>你可以一一使用 <code>echo ${array[n]}</code> 但这确实没有必要。有一个更好更简单的方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>${array[*]}</span></span></code></pre></div><p>这将为你提供所有数组元素。</p><p><img src="https://itsfoss.com/content/images/2023/07/accessing-all-array-elements-bash.png" alt="Accessing all array elements at once in bash shell"></p><h3 id="在-bash-中获取数组长度" tabindex="-1">在 Bash 中获取数组长度 <a class="header-anchor" href="#在-bash-中获取数组长度" aria-label="Permalink to “在 Bash 中获取数组长度”">​</a></h3>',26)),n("p",null,[s[1]||(s[1]=a("如何知道数组中有多少个元素？ 有一个专门的方法 ",-1)),i(e,{href:"https://linuxhandbook.com:443/array-length-bash/"},{default:t(()=>[...s[0]||(s[0]=[a("在 Bash 中获取数组长度",-1)])]),_:1}),s[2]||(s[2]=a("：",-1))]),s[24]||(s[24]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>${#array_name[@]}</span></span></code></pre></div><p>就这么简单，对吧？</p><p><img src="https://itsfoss.com/content/images/2023/07/get-array-length-bash.png" alt="Get array length in bash"></p><h3 id="在-bash-中添加数组元素" tabindex="-1">在 Bash 中添加数组元素 <a class="header-anchor" href="#在-bash-中添加数组元素" aria-label="Permalink to “在 Bash 中添加数组元素”">​</a></h3>',4)),n("p",null,[s[4]||(s[4]=a("如果必须向数组添加其他元素，请使用 ",-1)),s[5]||(s[5]=n("code",null,"+=",-1)),s[6]||(s[6]=a(" 运算符 ",-1)),i(e,{href:"https://linuxhandbook.com:443/bash-append-array/"},{default:t(()=>[...s[3]||(s[3]=[a("将元素追加到 Bash 中的现有数组",-1)])]),_:1}),s[7]||(s[7]=a("：",-1))]),s[25]||(s[25]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>array_name+=(&quot;new_value&quot;)</span></span></code></pre></div><p>这是一个例子：</p><p><img src="https://itsfoss.com/content/images/2023/07/append-element-to-array.png" alt="Append new element to array"></p><blockquote><p>🚧 追加元素时使用 <code>()</code> 很重要。</p></blockquote><p>你还可以使用索引将元素设置在任何位置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>array_name[N]=new_value</span></span></code></pre></div><p><strong>但请记住使用正确的索引编号。</strong> 如果在现有索引上使用它，新值将替换该元素。</p><p>如果你使用“越界”索引，它仍会添加到最后一个元素之后。例如，如果数组长度为 6，并且你尝试在索引 9 处设置新值，则该值仍将作为最后一个元素添加到第 7 个位置（索引 6）。</p><p><img src="https://itsfoss.com/content/images/2023/07/add-array-element-bash-1.png" alt=""></p><h3 id="删除数组元素" tabindex="-1">删除数组元素 <a class="header-anchor" href="#删除数组元素" aria-label="Permalink to “删除数组元素”">​</a></h3><p>你可以使用 Shell 内置的 <code>unset</code> 通过提供索引号来删除数组元素：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>unset array_name[N]</span></span></code></pre></div><p>这是一个示例，我删除了数组的第四个元素。</p><p><img src="https://itsfoss.com/content/images/2023/07/delete-array-element-bash.png" alt="Delete array element in bash"></p><p>你还可以通过 unset 来删除整个数组：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>unset array_name</span></span></code></pre></div><blockquote><p>💡 Bash 中没有严格的数据类型规则。你可以创建一个同时包含整数和字符串的数组。</p></blockquote><h3 id="🏋️-练习时间" tabindex="-1">🏋️ 练习时间 <a class="header-anchor" href="#🏋️-练习时间" aria-label="Permalink to “🏋️ 练习时间”">​</a></h3><p>让我们练习一下你所学到的有关 Bash 数组的知识。</p><p><strong>练习 1</strong>：创建一个 Bash 脚本，其中包含五个最佳 Linux 发行版的数组。全部打印出来。</p><p>现在，用 “Hannah Montanna Linux” 替换中间的选择。</p><p><strong>练习 2</strong>：创建一个 Bash 脚本，该脚本接受用户提供的三个数字，然后以相反的顺序打印它们。</p><p>预期输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Enter three numbers and press enter</span></span>
<span class="line"><span>12 23 44</span></span>
<span class="line"><span>Numbers in reverse order are: 44 23 12</span></span></code></pre></div><p>我希望你喜欢通过本系列学习 Bash Shell 脚本。在下一章中，你将学习如何使用 <code>if-else</code>。敬请关注。</p><p><em>（题图：MJ/09477e2f-2bf9-4fdf-bc1e-c894a068adf2）</em></p><hr>`,27)),n("p",null,[s[9]||(s[9]=a("via: ",-1)),i(e,{href:"https://itsfoss.com/bash-arrays/"},{default:t(()=>[...s[8]||(s[8]=[a("https://itsfoss.com/bash-arrays/",-1)])]),_:1})]),n("p",null,[s[14]||(s[14]=a("作者：",-1)),i(e,{href:"https://itsfoss.com/author/abhishek/"},{default:t(()=>[...s[10]||(s[10]=[a("Abhishek Prakash",-1)])]),_:1}),s[15]||(s[15]=a(" 选题：",-1)),i(e,{href:"https://github.com/lkxed/"},{default:t(()=>[...s[11]||(s[11]=[a("lkxed",-1)])]),_:1}),s[16]||(s[16]=a(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[12]||(s[12]=[a("geekpi",-1)])]),_:1}),s[17]||(s[17]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[19]||(s[19]=[a("Linux中国",-1)])]),_:1}),s[22]||(s[22]=a(" 荣誉推出",-1))])])}const x=p(d,[["render",g]]);export{B as __pageData,x as default};
